List<Cloud_News__e> events = new List<Cloud_News__e>{
    new Cloud_News__e(Location__c = 'Mountain City', Urgent__c = true,
                      News_Content__c = 'Lake Road is closed due to mudslides.')
};
List<Database.SaveResult> results = EventBus.publish(events);
for (Database.SaveResult sr : results) {
    if (!sr.isSuccess()) {
        System.debug(sr.getErrors()[0].getMessage());   // 예외를 던지지 않으므로 직접 확인
    }
}

trigger CloudNewsTrigger on Cloud_News__e (after insert) {
    Group queue = [SELECT Id FROM Group WHERE Name = 'Regional Dispatch' AND Type = 'Queue'];
    List<Case> cases = new List<Case>();
    for (Cloud_News__e ev : Trigger.new) {
        if (ev.Urgent__c) {
            cases.add(new Case(Priority = 'High', Subject = 'News team dispatch to ' + ev.Location__c,
                               OwnerId = queue.Id));   // 실행 사용자가 Automated Process라서 소유자 지정
        }
    }
    insert cases;
}
